const jobId = String($json.job_id ?? '')
  .trim()
  .toLowerCase();

const uuidPattern =
  /^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/;

if (!uuidPattern.test(jobId)) {
  throw new Error('job_id must be a valid UUID');
}

return [{ json: { job_id: jobId } }];

if ($json.ready_to_run !== true || $json.status !== 'processing' || $json.current_stage !== 'render') {
  throw new Error(
    `Render stage could not start for job ${$json.job_id}: ` +
    `ready=${$json.ready_to_run}, status=${$json.status}, current_stage=${$json.current_stage}`
  );
}
return [{ json: { job_id: $json.job_id } }];

const errorItem = $input.first()?.json ?? {};
const job = $('Require Eligible Render Job').first().json;
if (typeof job.job_id !== 'string' || job.job_id.trim() === '') {
  throw new Error('Validated job_id is unavailable while recording render failure');
}
function extract(value) {
  if (typeof value === 'string' && value.trim()) {
    const raw=value.trim();
    const brace=raw.indexOf('{');
    if (brace>=0) {
      try {
        const parsed=JSON.parse(raw.slice(brace));
        if (typeof parsed?.message === 'string' && parsed.message.trim()) return parsed.message.trim();
        if (typeof parsed?.error === 'string' && parsed.error.trim()) return parsed.error.trim();
      } catch {}
    }
    return raw;
  }
  if (value && typeof value === 'object') {
    for (const key of ['message','description','errorMessage','errorDescription','body','response']) {
      const found=extract(value[key]);
      if (found) return found;
    }
    const nested=extract(value.error);
    if (nested) return nested;
  }
  return '';
}
let message = extract(errorItem.error) || extract(errorItem) || 'Unknown video render stage failure';
message = String(message).trim().slice(0, 4000);
return [{ json: { job_id: job.job_id, last_error: message } }];
